From 4743ad6c75601de105de8792bf400f22a94a431c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:41:56 +0100
Subject: [PATCH] containments/desktop: give the folder view focus once it
 loads

The desktop forwarded its initial focus to the folder view before the
view was loaded, so after Show Desktop the arrow keys did nothing until
the desktop was clicked once. Forward the focus when the view loads.

BUG: 519265
---
 containments/desktop/package/contents/ui/main.qml | 6 ++++++
 1 file changed, 6 insertions(+)

diff --git a/containments/desktop/package/contents/ui/main.qml b/containments/desktop/package/contents/ui/main.qml
index d3f413b2df..1eee3e5f45 100644
--- a/containments/desktop/package/contents/ui/main.qml
+++ b/containments/desktop/package/contents/ui/main.qml
@@ -419,6 +419,12 @@ ContainmentItem {
                 }
                 asynchronous: false

+                onLoaded: {
+                    if (root.focus) {
+                        item.forceActiveFocus();
+                    }
+                }
+
                 onFocusChanged: {
                     if (!focus && model) {
                         model.clearSelection();
-- 
2.53.0
